import { addDays } from './date';

export type RoadmapProblem = { id: number; title: string; difficulty: string | null };
export type DueRoadmapProblem = RoadmapProblem & { dueDate: string };
export type RoadmapDay = { date: string; reviews: DueRoadmapProblem[]; newItems: RoadmapProblem[] };

/** Forecast the known due reviews plus the first-pass new-question pace. Future
 * reviews generated by questions answered later are intentionally recalculated
 * on each day from the real FSRS history instead of guessed here. */
export function buildFirstPassRoadmap(input: {
  firstDate: string;
  remainingNewItems: RoadmapProblem[];
  dueReviews: DueRoadmapProblem[];
  dailyQuestionLimit: number;
  maxNewPerDay?: number;
}): RoadmapDay[] {
  const { firstDate, remainingNewItems, dueReviews, dailyQuestionLimit } = input;
  const dailyLimit = Math.max(1, Math.floor(dailyQuestionLimit));
  const maxNewPerDay = Math.min(2, Math.max(1, Math.floor(input.maxNewPerDay ?? 2)), dailyLimit);
  const reviewLimit = Math.min(3, Math.max(0, dailyLimit - 1));
  const scheduledReviewIds = new Set<number>();
  const days: RoadmapDay[] = [];
  let nextNewIndex = 0;

  for (let offset = 0; nextNewIndex < remainingNewItems.length && offset < 365; offset += 1) {
    const date = addDays(firstDate, offset);
    const dueToday = dueReviews
      .filter(item => !scheduledReviewIds.has(item.id) && item.dueDate <= date)
      .sort((a, b) => a.dueDate.localeCompare(b.dueDate) || a.id - b.id);
    const reviews = dueToday.slice(0, reviewLimit);
    reviews.forEach(item => scheduledReviewIds.add(item.id));

    const targetNew = dueToday.length >= 3 ? 1 : maxNewPerDay;
    const newCount = Math.min(targetNew, dailyLimit - reviews.length, remainingNewItems.length - nextNewIndex);
    const newItems = remainingNewItems.slice(nextNewIndex, nextNewIndex + newCount);
    nextNewIndex += newItems.length;
    days.push({ date, reviews, newItems });
  }

  return days;
}
